// The sites this digest reads. One entry per Gluecrawl job.
//
// Create each job once, against the site's news index, then paste its id
// here. Job creation runs the LLM mapper and is charged upfront; the runs
// this workflow starts replay that cached configuration instead.
//
// Each job needs an article_body column, or the digest has only headlines to
// work from. The overview note lists the full column set.
const SOURCES = [
  { source: 'Ars Technica AI', job_id: '00000000-0000-0000-0000-000000000000' },
  { source: 'VentureBeat AI', job_id: '00000000-0000-0000-0000-000000000000' },
  { source: 'The Verge AI', job_id: '00000000-0000-0000-0000-000000000000' },
];

return SOURCES.map((source) => ({ json: source }));

// Every job's mapper names its own columns, so the same field arrives as
// `link` from one site and `url` from the next. Fold the common spellings
// onto one shape and drop anything without a usable link.
const ALIASES = {
  url: ['url', 'link', 'href', 'articleurl', 'permalink'],
  title: ['title', 'headline', 'name', 'heading'],
  summary: ['summary', 'description', 'excerpt', 'snippet', 'standfirst', 'subtitle', 'teaser'],
  body: ['body', 'content', 'articlebody', 'articletext', 'fulltext', 'text', 'story', 'maincontent'],
  published_at: ['publishedat', 'published', 'date', 'datetime', 'time', 'timestamp', 'posted'],
};

// What gets kept per article. The archive is append-only and never pruned,
// so an untrimmed body would grow it without bound for no extra editorial
// value — the digest only ever quotes the opening of a piece.
const BODY_LIMIT = 4000;

const key = (name) => name.toLowerCase().replace(/[^a-z0-9]/g, '');

function pick(row, names) {
  const flat = {};
  for (const [k, v] of Object.entries(row)) flat[key(k)] = v;
  for (const name of names) {
    const value = flat[name];
    // A column can come back as an array — a body collected from separate
    // paragraph nodes arrives that way, and Gluecrawl types such a column
    // `array`. Flatten before testing, or the field reads as missing.
    const text = Array.isArray(value) ? value.filter(Boolean).join('\n\n') : value;
    if (typeof text === 'string' && text.trim()) return text.trim();
    if (typeof text === 'number') return String(text);
  }
  return '';
}

const scrapedAt = new Date().toISOString();
const seen = new Set();
const articles = [];

for (const [index, item] of $input.all().entries()) {
  const row = item.json ?? {};

  // A source whose run failed arrives as an error item, because the scrape
  // node is set to continue. Skipping it keeps one broken site from taking
  // the whole digest down with it.
  if (row.error) continue;

  const url = pick(row, ALIASES.url);
  if (!/^https?:\/\//i.test(url) || seen.has(url)) continue;
  seen.add(url);

  // Prefer the label the user wrote next to the job id; fall back to the
  // hostname when item lineage is unavailable.
  let source = '';
  try {
    source = $('News Sources').itemMatching(index).json.source ?? '';
  } catch (error) {
    source = '';
  }
  if (!source) {
    try {
      source = new URL(url).hostname.replace(/^www\./, '');
    } catch (error) {
      source = 'unknown';
    }
  }

  articles.push({
    json: {
      url,
      title: pick(row, ALIASES.title) || url,
      summary: pick(row, ALIASES.summary),
      body: pick(row, ALIASES.body).slice(0, BODY_LIMIT),
      published_at: pick(row, ALIASES.published_at),
      source,
      scraped_at: scrapedAt,
    },
    pairedItem: { item: index },
  });
}

return articles;

// Collapse the week into a single item. The model has to see every story at
// once to group them; one prompt per article would only ever produce a list.
//
// Each story contributes an excerpt rather than its whole body. The digest
// needs enough to tell what happened and who it affects; a week of full
// articles would cost more to summarise than it cost to scrape.
const EXCERPT = 1200;

const articles = $input.all().map((item) => item.json);

const bySource = {};
for (const article of articles) {
  (bySource[article.source] ??= []).push(article);
}

const brief = Object.entries(bySource)
  .map(([source, rows]) => {
    const entries = rows.map((row) => {
      const parts = [`### ${row.title}`, row.url];
      if (row.published_at) parts.push(`Published: ${row.published_at}`);
      // The body is the point; the listing summary is only a fallback for
      // sources whose jobs never had detail extraction enabled.
      const text = row.body || row.summary;
      if (text) parts.push(text.slice(0, EXCERPT));
      return parts.join('\n');
    });
    return `## ${source}\n\n${entries.join('\n\n')}`;
  })
  .join('\n\n');

return [
  {
    json: {
      week_of: new Date().toISOString().slice(0, 10),
      article_count: articles.length,
      // Reads zero when the jobs are only mapping listing pages, which is the
      // quickest way to tell a thin digest from a broken one.
      with_body: articles.filter((row) => row.body).length,
      sources: Object.keys(bySource).join(', '),
      brief,
    },
  },
];
